using Humcp.Schema;

namespace Humcp.Core.Tests;

/// <summary>
/// The add-or-edit server form: humcp's own settings, generated by the same engine as every tool's
/// form, and read back from the boxes rather than through the omission rule.
/// </summary>
public class ServerFormTests
{
    private static readonly ServerDescriptor Everything = new(
        "everything", "Everything", "npx", ["-y", "@modelcontextprotocol/server-everything"], "C:\\work")
    {
        Environment = new Dictionary<string, string> { ["TOKEN"] = "a=b" },
    };

    private static FormState Filled(ServerDescriptor? current)
    {
        var state = FormState.Create(ServerForm.Model);
        ServerForm.Fill(state, current);
        return state;
    }

    [Fact]
    public void Every_field_renders_as_a_native_control()
    {
        // The form exists to prove the generator on humcp's own settings; a field that fell to a
        // JSON editor would be humcp failing its own test.
        Assert.All(ServerForm.Model.Fields, f => Assert.Equal(FieldTier.Direct, f.Tier));
        Assert.All(ServerForm.ImportModel.Fields, f => Assert.Equal(FieldTier.Direct, f.Tier));
        Assert.Equal(FieldKind.MultilineText, Assert.Single(ServerForm.ImportModel.Fields).Kind);
    }

    [Fact]
    public void An_entry_filled_in_and_read_back_is_the_same_entry()
    {
        var read = ServerForm.Read(Filled(Everything), "everything", Everything, out var problem);

        Assert.Null(problem);
        Assert.NotNull(read);
        Assert.Equal(Everything.DisplayName, read.DisplayName);
        Assert.Equal(Everything.Command, read.Command);
        Assert.Equal(Everything.Arguments, read.Arguments);
        Assert.Equal(Everything.WorkingDirectory, read.WorkingDirectory);

        // Split on the first equals sign only: a value is allowed one of its own.
        Assert.Equal("a=b", read.Environment["TOKEN"]);
        Assert.True(read.Enabled);
    }

    [Fact]
    public void A_cleared_box_means_empty_rather_than_unchanged()
    {
        var state = Filled(Everything);
        ((TextFieldState)state.Find(ServerForm.DirectoryField)!).Text = "";

        var read = ServerForm.Read(state, "everything", Everything, out _);

        // Through the omission rule this would have read as "not touched" and kept C:\work.
        Assert.Null(read!.WorkingDirectory);
    }

    [Fact]
    public void A_new_server_starts_ticked_and_otherwise_empty()
    {
        var state = Filled(null);

        Assert.True(((BooleanFieldState)state.Find(ServerForm.EnabledField)!).Value);
        Assert.Equal("", ((TextFieldState)state.Find(ServerForm.CommandField)!).Text);
    }

    [Fact]
    public void A_server_with_no_command_is_refused_with_a_reason()
    {
        var state = Filled(null);
        ((TextFieldState)state.Find(ServerForm.NameField)!).Text = "x";

        Assert.Null(ServerForm.Read(state, "x", null, out var problem));
        Assert.StartsWith("Command:", problem);
    }

    [Fact]
    public void A_variable_that_is_not_name_equals_value_is_refused()
    {
        var state = Filled(Everything);
        var list = (ListFieldState)state.Find(ServerForm.EnvironmentField)!;
        ((TextFieldState)list.Draft).Text = "no equals sign";
        list.AddDraft();

        Assert.Null(ServerForm.Read(state, "everything", Everything, out var problem));
        Assert.StartsWith("Environment variables:", problem);

        // And the schema says so too, so the field is marked before the button is pressed.
        Assert.True(state.Prepare().HasIssues);
    }

    [Fact]
    public void A_server_reached_by_address_is_added_with_no_command()
    {
        var remote = new ServerDescriptor("r", "Remote", "", []) { Url = "https://example.com/mcp" };

        var read = ServerForm.Read(Filled(remote), "r", remote, out var problem);

        Assert.Null(problem);
        Assert.Equal("https://example.com/mcp", read!.Url);
        Assert.Equal("", read.Command);
    }

    [Theory]
    [InlineData("npx", "https://example.com/mcp", "not both")]
    [InlineData("", "ms-settings:privacy", "https://")]
    [InlineData("", "", "or an address")]
    public void Command_and_address_are_one_or_the_other(string command, string address, string said)
    {
        var state = Filled(null);
        ((TextFieldState)state.Find(ServerForm.NameField)!).Text = "x";
        ((TextFieldState)state.Find(ServerForm.CommandField)!).Text = command;
        ((TextFieldState)state.Find(ServerForm.AddressField)!).Text = address;

        Assert.Null(ServerForm.Read(state, "x", null, out var problem));
        Assert.Contains(said, problem);
    }
}
